      "file": "src/engine/nativeSceneCombatArena.ts",
      "name": "shrinkArenaPockets",
      "target": "sceneShrinkArenaPockets",
      "kind": "method",
      "before": "shrinkArenaPockets(actor: Actor, by: number, min: number): void {\n    if (!this.airPockets.length) return;\n    for (const ap of this.airPockets) ap.r = Math.max(min, ap.r - by);\n    const rec = this.arenaSinks.get(actor.id);\n    if (rec && rec.radius > 0) this.paintSink(actor, rec);\n  }",
